<script setup>
import { hrUrl } from '@/utilities/hrUrl';
import { Head, Link, useForm } from '@inertiajs/vue3'; import AppLayout from '@/Layouts/AppLayout.vue'; import Button from '@/Components/Shadcn/Button.vue'; import PageHeader from '@/Components/UI/PageHeader.vue'; import { ArrowLeft, Pencil } from 'lucide-vue-next'; import AttendanceForm from './AttendanceForm.vue';
defineOptions({layout:AppLayout}); const props=defineProps({record:Object,employees:[Array,Object]}); const local=(value)=>value?value.slice(0,16):''; const form=useForm({employee_uuid:props.record.employee.uuid,started_at:local(props.record.started_at),ended_at:local(props.record.ended_at),observation:props.record.observation??''}); const submit=()=>form.put(hrUrl(`/administration/attendance/${props.record.uuid}`));
</script>
<template><Head title="Corriger une présence"/><div class="space-y-5"><PageHeader :eyebrow="`${record.employee.employee_number} · Correction auditée`" title="Corriger la session" :description="`Session de ${record.employee.name}. La date de travail sera recalculée depuis l’heure d’entrée.`" :icon="Pencil" tone="violet"><template #actions><Button :as="Link" :href="hrUrl('/administration/attendance')" variant="outline"><ArrowLeft class="h-4 w-4"/>Retour aux présences</Button></template></PageHeader><AttendanceForm :form="form" :employees="employees" :cancel-href="hrUrl('/administration/attendance')" submit-label="Enregistrer la correction" @submit="submit"/></div></template>
